package dk.stream.android;
import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.*;
import java.io.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.zip.*;
import okhttp3.*;
import org.json.*;

@androidx.media3.common.util.UnstableApi
public final class MediaDownloadService extends Service {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private final AtomicInteger jobs=new AtomicInteger();private volatile boolean cancelled;private volatile WebDavClient cloud;private PowerManager.WakeLock wake;
 private final OkHttpClient http=new OkHttpClient.Builder().connectTimeout(20,TimeUnit.SECONDS).readTimeout(60,TimeUnit.SECONDS).build();private long lastUpdate;
 @Override public void onCreate(){super.onCreate();if(Build.VERSION.SDK_INT>=26)((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(new NotificationChannel("downloads","Downloads",NotificationManager.IMPORTANCE_LOW));wake=((PowerManager)getSystemService(POWER_SERVICE)).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"Stream:downloads");wake.acquire(6*60*60*1000L);}
 @Override public android.os.IBinder onBind(Intent intent){return null;}
 private Notification notice(String name,String text,int total,int done){Notification.Builder builder=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,"downloads"):new Notification.Builder(this);return builder.setSmallIcon(R.drawable.ic_download).setContentTitle(name).setContentText(text).setOngoing(true).setOnlyAlertOnce(true).setProgress(total,done,total==0).build();}
 @Override public int onStartCommand(Intent intent,int flags,int startId){if(intent==null||intent.getData()==null){stopSelf(startId);return START_NOT_STICKY;}startForeground(2010,notice("Download","Starter …",0,0));jobs.incrementAndGet();String plan=intent.getStringExtra("plan");Uri destination=intent.getData();worker.execute(()->download(plan,destination,startId));return START_NOT_STICKY;}
 private void download(String planName,Uri destination,int startId){String name="Download";boolean success=false,writing=false;try{JSONObject plan=MediaDownloads.read(this,planName);name=plan.getString("name");JSONArray files=plan.getJSONArray("files");for(int i=0;i<files.length();i++)if(destination.toString().equals(files.getJSONObject(i).getString("uri")))throw new IOException("Source and destination are identical");Library library=new LibraryStore(this).load();cloud=library.pcloud==null?null:new WebDavClient(library.pcloud);lastUpdate=0;try(OutputStream raw=getContentResolver().openOutputStream(destination,"wt")){if(raw==null)throw new IOException("Cannot write destination");writing=true;java.util.List<String> names=new java.util.ArrayList<>();for(int i=0;i<files.length();i++)names.add(files.getJSONObject(i).getString("name"));final String title=name;DownloadArchive.write(names,raw,(index,output)->copy(files.getJSONObject(index),output,library,title,files.length(),index));}success=true;
  }catch(Exception failure){new Handler(Looper.getMainLooper()).post(()->android.widget.Toast.makeText(this,"Download mislykkedes. Kontrollér netværk og adgang til filerne.",android.widget.Toast.LENGTH_LONG).show());}
  finally{if(!success&&writing)try{android.provider.DocumentsContract.deleteDocument(getContentResolver(),destination);}catch(Exception ignored){}if(cloud!=null)cloud.cancel();cloud=null;try{MediaDownloads.file(this,planName).delete();}catch(Exception ignored){}if(jobs.decrementAndGet()==0){androidx.core.app.ServiceCompat.stopForeground(this,androidx.core.app.ServiceCompat.STOP_FOREGROUND_REMOVE);stopSelf(startId);}complete(name,destination,success);}
 }
 private void copy(JSONObject file,OutputStream output,Library library,String name,int total,int done)throws Exception{String uri=file.getString("uri");try(InputStream input=open(uri,library)){if(input==null)throw new IOException("Cannot read file");byte[] buffer=new byte[65536];int n;while((n=input.read(buffer))!=-1){if(cancelled||Thread.currentThread().isInterrupted())throw new InterruptedIOException();output.write(buffer,0,n);long now=SystemClock.elapsedRealtime();if(now-lastUpdate>=1000){lastUpdate=now;((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(2010,notice(name,(done+1)+" / "+total+" · "+file.getString("name"),total,done));}}}}
 private InputStream open(String value,Library library)throws IOException{if(PcloudDocument.is(value)){if(cloud==null)throw new IOException("pCloud account missing");return cloud.open(PcloudDocument.url(library.pcloud,value),0);}if(value.startsWith("content:"))return getContentResolver().openInputStream(Uri.parse(value));Response response=http.newCall(new Request.Builder().url(Playlist.httpUrl(value)).build()).execute();if(!response.isSuccessful()||response.body()==null){response.close();throw new IOException("HTTP download failed");}return new FilterInputStream(response.body().byteStream()){@Override public void close()throws IOException{try{super.close();}finally{response.close();}}};}
 @android.annotation.SuppressLint("MissingPermission") private void complete(String name,Uri destination,boolean success){if(success)new Handler(Looper.getMainLooper()).post(()->android.widget.Toast.makeText(this,"Download færdig: "+name,android.widget.Toast.LENGTH_LONG).show());Notification.Builder builder=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,"downloads"):new Notification.Builder(this);builder.setSmallIcon(R.drawable.ic_download).setContentTitle(success?"Download færdig":"Download mislykkedes").setContentText(name).setAutoCancel(true);if(success){Intent open=new Intent(Intent.ACTION_VIEW).setDataAndType(destination,"*/*").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_ACTIVITY_NEW_TASK);builder.setContentIntent(PendingIntent.getActivity(this,2011,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));}((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(2011,builder.build());}
 @Override public void onTimeout(int startId,int type){cancelled=true;http.dispatcher().cancelAll();if(cloud!=null)cloud.cancel();stopSelf();}
 @Override public void onDestroy(){cancelled=true;http.dispatcher().cancelAll();if(cloud!=null)cloud.cancel();worker.shutdownNow();if(wake!=null&&wake.isHeld())wake.release();super.onDestroy();}
}
